<script setup lang="ts">
import {ref, computed, onMounted, onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAccount} from './store'
import {api} from './api'
const account=useAccount(), route=useRoute(), router=useRouter()
const email=ref(''),code=ref(''),error=ref(''),notice=ref(''),busy=ref(false),accountOpen=ref(false),mobileOpen=ref(false),prefs=ref<any>({}),consent=ref(false)
const nav=[['/chat','智能助手'],['/shops','发现店铺'],['/community','探店社区'],['/orders','我的订单'],['/coupons','我的券包']]
const title=computed(()=>nav.find(n=>route.path.startsWith(n[0]))?.[1]||'巷口')
function expired(){account.clear();accountOpen.value=false}
async function guestLogin(){busy.value=true;error.value='';try{const data=await api('/api/auth/guest-login','POST');account.user=data.user;await account.refreshSessions()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>{account.boot();window.addEventListener('auth-expired',expired)})
onUnmounted(()=>window.removeEventListener('auth-expired',expired))
async function run(fn:()=>Promise<unknown>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function settings(){accountOpen.value=true;await run(async()=>{prefs.value=(await api('/api/memory')).preferences||{}})}
async function deleteSession(id:string){if(!confirm('删除此会话？'))return;await run(async()=>{await api(`/api/sessions/${id}`,'DELETE');await account.refreshSessions();if(route.params.id===id)await router.push('/chat')})}
async function newChat(){mobileOpen.value=false;await router.push('/chat');window.dispatchEvent(new Event('new-chat'))}
function go(path:string){mobileOpen.value=false;router.push(path)}
</script>
<template>
<div class="shell"><aside :class="['sidebar',{open:mobileOpen}]"><div class="brand">巷口<small>你的城市生活助手</small></div><button class="primary new-chat" :disabled="!account.user" @click="newChat">＋ 开启新对话</button><nav><button v-for="item in nav" :key="item[0]" :class="{active:route.path.startsWith(item[0])}" @click="go(item[0])"><span>{{item[1]}}</span></button></nav><div class="history"><div class="eyebrow">最近会话</div><div v-for="s in account.sessions" :key="s.session_id" :class="['history-item',{selected:route.params.id===s.session_id}]"><button @click="go('/chat/'+s.session_id)">{{s.title}}</button><button class="delete" aria-label="删除会话" @click="deleteSession(s.session_id)">×</button></div><p v-if="!account.sessions.length" class="muted small">登录后，对话会保存在这里。</p></div><button class="account" @click="account.user?settings():null"><span class="avatar">{{account.user?.nickName?.slice(0,1)||'你'}}</span><span><b>{{account.user?.nickName||'请先登录'}}</b><small>账号与长期偏好</small></span><span class="dots">···</span></button></aside><main class="workspace"><header><button class="mobile-menu" @click="mobileOpen=!mobileOpen" aria-label="导航">☰</button><div><h1>{{title}}</h1><small class="muted">一起安排城市生活</small></div><div class="header-right"><span class="badge">点评 × Agent</span></div></header><div class="global-error" v-if="error" role="alert">{{error}}</div><RouterView v-if="account.user" v-slot="{ Component }"><keep-alive include="Chat"><component :is="Component" :key="account.generation"/></keep-alive></RouterView><div v-else class="login-page"><div class="login-card"><div class="eyebrow">WELCOME TO XIANGKOU</div><h2>先登录，再一起探索城市</h2><p class="muted">聊天、探店社区、订单和券包使用同一个点评账号。</p><form @submit.prevent="run(()=>account.login(email,code))"><label>邮箱<input v-model="email" required type="email" maxlength="50" inputmode="email" autocomplete="email" placeholder="请输入邮箱"></label><label>验证码<div class="inline"><input v-model="code" required pattern="[0-9]{6}" maxlength="6" inputmode="numeric" autocomplete="one-time-code" placeholder="6 位验证码"><button type="button" class="outline" :disabled="busy||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)" @click="run(async()=>{await api('/api/auth/code','POST',{email});notice='验证码已发送到你的邮箱（未配置发件邮箱时，可到本地 Redis 取码）。'})">获取验证码</button></div></label><button class="primary" :disabled="busy||!account.ready">{{busy?'正在处理…':'登录 巷口'}}</button><button class="outline" style="margin-top:12px;width:100%" :disabled="busy" @click="guestLogin">游客体验（免登录）</button></form><p v-if="notice" class="small" style="color:#2e7d32">{{notice}}</p><p class="small muted">验证码发送到邮箱；未配置发件邮箱时写入本地 Redis。支付仅为本地模拟。</p></div></div></main></div>
<div class="overlay" v-if="accountOpen" @click.self="accountOpen=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="account-title"><button class="close" aria-label="关闭" @click="accountOpen=false">×</button><h2 id="account-title">账号与长期偏好</h2><p>{{account.user?.nickName}}</p><label>常选类别<input v-model="prefs.category" maxlength="30" placeholder="例如：美食、KTV"></label><label>常用商圈<input v-model="prefs.area" maxlength="30" placeholder="例如：运河上街"></label><div class="inline"><label>人均预算上限<input type="number" v-model.number="prefs.max_price" min="1" max="100000" placeholder="元"></label><label>最低评分<input type="number" v-model.number="prefs.min_score" min="0" max="5" step="0.1"></label></div><label class="check"><input type="checkbox" v-model="prefs.wants_coupon">优先查看优惠券</label><label class="check"><input type="checkbox" v-model="prefs.wants_notes">推荐时查看探店笔记</label><label class="check"><input type="checkbox" v-model="consent">我同意保存这些偏好，用于跨会话推荐</label><div class="actions"><button class="outline" :disabled="busy" @click="accountOpen=false;router.push('/users/'+account.user.id)">我的主页</button><button class="outline" :disabled="busy" @click="run(()=>account.logout());accountOpen=false">退出登录</button><button class="outline" :disabled="busy" @click="run(async()=>{await api('/api/memory','DELETE');prefs={}})">清除记忆</button><button class="primary" :disabled="busy||!consent" @click="run(()=>api('/api/memory','PUT',{consent:true,preferences:{...prefs,category:prefs.category||null,area:prefs.area||null,max_price:prefs.max_price||null,min_score:prefs.min_score===''?null:prefs.min_score}}))">保存偏好</button></div></section></div>
</template>
